INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation)
VALUES
('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/1] การนับช่วงเวลา: ทศวรรษ', 'easy', 'mcq', 'ช่วงเวลา "ทศวรรษ" หมายถึงรอบระยะเวลากี่ปี?', '["5 ปี","10 ปี","50 ปี","100 ปี"]'::jsonb, 1, 'ทศวรรษ (Decade) หมายถึง ช่วงเวลา 10 ปี โดยเริ่มนับจากปีที่ลงท้ายด้วย 0 ไปจนถึงปีที่ลงท้ายด้วย 9'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/1] การนับช่วงเวลา: ศตวรรษ', 'easy', 'mcq', 'คำว่า "ศตวรรษ" หมายถึงรอบระยะเวลากี่ปี?', '["10 ปี","50 ปี","100 ปี","1,000 ปี"]'::jsonb, 2, 'ศตวรรษ (Century) หมายถึง ช่วงเวลารอบ 100 ปี เริ่มนับจากปีที่ลงท้ายด้วย 1 จนถึงปีที่ลงท้ายด้วย 100 หรือ 00'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/1] การนับช่วงเวลา: สหัสวรรษ', 'easy', 'mcq', 'ช่วงเวลา "สหัสวรรษ" หมายถึงรอบระยะเวลากี่ปี?', '["100 ปี","500 ปี","1,000 ปี","10,000 ปี"]'::jsonb, 2, 'สหัสวรรษ (Millennium) หมายถึง รอบระยะเวลา 1,000 ปี'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/1] การคำนวณศตวรรษในพุทธศักราช', 'medium', 'mcq', 'ปี พ.ศ. 2567 จัดอยู่ในพุทธศตวรรษที่เท่าใด?', '["พุทธศตวรรษที่ 24","พุทธศตวรรษที่ 25","พุทธศตวรรษที่ 26","พุทธศตวรรษที่ 27"]'::jsonb, 2, 'พุทธศตวรรษที่ 26 เริ่มนับจาก พ.ศ. 2501 ถึง พ.ศ. 2600 ดังนั้นปี พ.ศ. 2567 จึงอยู่ในพุทธศตวรรษที่ 26'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/1] การคำนวณคริสต์ศตวรรษ', 'hard', 'mcq', 'ปี ค.ศ. 2024 จัดอยู่ในคริสต์ศตวรรษที่เท่าใด?', '["คริสต์ศตวรรษที่ 19","คริสต์ศตวรรษที่ 20","คริสต์ศตวรรษที่ 21","คริสต์ศตวรรษที่ 22"]'::jsonb, 2, 'คริสต์ศตวรรษที่ 21 เริ่มต้นตั้งแต่วันที่ 1 มกราคม ค.ศ. 2001 ถึง ค.ศ. 2100'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] การแบ่งยุคสมัย: ยุคก่อนประวัติศาสตร์และยุคประวัติศาสตร์', 'easy', 'mcq', 'เกณฑ์สำคัญที่สุดที่นักประวัติศาสตร์ใช้แบ่งระหว่าง "ยุคก่อนประวัติศาสตร์" กับ "ยุคประวัติศาสตร์" คือข้อใด?', '["การรู้จักใช้ไฟ","การประดิษฐ์และบันทึกด้วยตัวอักษร","การสร้างบ้านเรือน","การรู้จักเพาะปลูกพืช"]'::jsonb, 1, 'ยุคประวัติศาสตร์เริ่มต้นเมื่อมนุษย์เริ่มรู้จักการประดิษฐ์ตัวอักษรและบันทึกเรื่องราวเป็นลายลักษณ์อักษร'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] ยุคก่อนประวัติศาสตร์: ยุคหินเก่า', 'medium', 'mcq', 'ลักษณะการดำรงชีวิตของมนุษย์ใน "ยุคหินเก่า" ตรงกับข้อใด?', '["สร้างบ้านแปงเมืองอย่างเป็นระเบียบ","เร่ร่อนเก็บของป่า ล่าสัตว์ อาศัยตามถ้ำหรือเพิงผา ใช้เครื่องมือหินกะเทาะหยาบๆ","รู้จักการทำเกษตรกรรมและเลี้ยงสัตว์ในคอก","รู้จักการถลุงแร่เหล็กสร้างดาบ"]'::jsonb, 1, 'มนุษย์ยุคหินเก่ายังไม่ตั้งถิ่นฐานเป็นหลักแหล่ง อาศัยถ้ำธรรมชาติ ล่าสัตว์ และใช้เครื่องมือหินกะเทาะแบบหยาบ'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] ยุคหินใหม่', 'medium', 'mcq', 'การเปลี่ยนแปลงสำคัญที่สุดที่ทำให้มนุษย์ก้าวเข้าสู่ "ยุคหินใหม่" คือข้อใด?', '["การเริ่มทำการเพาะปลูก เลี้ยงสัตว์ และสร้างชุมชนถาวร รู้จักขัดเครื่องมือหินจนเรียบคม","การค้นพบเครื่องบิน","การเริ่มใช้เงินตรา","การมีคอมพิวเตอร์"]'::jsonb, 0, 'ยุคหินใหม่เกิดการปฏิวัติเกษตรกรรม มนุษย์เริ่มตั้งถิ่นฐานเป็นหลักแหล่ง ทำเครื่องปั้นดินเผา และใช้เครื่องมือหินขัด'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] ยุคโลหะ: ยุคสัมฤทธิ์', 'hard', 'mcq', 'โลหะ "สัมฤทธิ์" เกิดจากการหลอมผสมระหว่างแร่ชนิดใดเข้าด้วยกัน?', '["ทองแดง กับ ดีบุก","เหล็ก กับ สังกะสี","ทองคำ กับ เงิน","อะลูมิเนียม กับ ตะกั่ว"]'::jsonb, 0, 'สัมฤทธิ์ (Bronze) เป็นโลหะผสมระหว่างทองแดงกับดีบุก มีความแข็งแรงกว่าทองแดงบริสุทธิ์'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] ยุคโลหะ: ยุคเหล็ก', 'medium', 'mcq', 'ข้อดีของเครื่องมือเครื่องใช้ที่ทำจาก "เหล็ก" เมื่อเทียบกับสัมฤทธิ์คืออะไร?', '["มีสีสันสวยงามกว่า","มีความแข็งแกร่ง ทนทาน และมีแหล่งแร่หาง่ายกว่า จึงนำมาทำอาวุธและคันไถ","มีน้ำหนักเบากว่ามาก","ละลายในน้ำได้"]'::jsonb, 1, 'เหล็กมีความแข็งแรง ทนทาน และคมกว่าสัมฤทธิ์มาก ทำให้การเกษตร (คันไถ) และอาวุธมีประสิทธิภาพสูงขึ้น'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] การนับศักราช: พ.ศ. และ ค.ศ.', 'easy', 'mcq', 'พุทธศักราช (พ.ศ.) เริ่มนับเมื่อเกิดเหตุการณ์ใด?', '["พระพุทธเจ้าประสูติ","พระพุทธเจ้าตรัสรู้","พระพุทธเจ้าเสด็จดับขันธ์ปรินิพพาน","พระพุทธเจ้าทรงแสดงปฐมเทศนา"]'::jsonb, 2, 'ในประเทศไทย พุทธศักราชเริ่มนับ พ.ศ. 1 เมื่อพระพุทธเจ้าเสด็จดับขันธ์ปรินิพพานไปแล้วครบ 1 ปี'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] คริสต์ศักราช (ค.ศ.)', 'easy', 'mcq', 'คริสต์ศักราช (ค.ศ.) เริ่มนับเริ่มต้นจากปีที่เกิดเหตุการณ์ใด?', '["ปีที่พระเยซูสิ้นพระชนม์","ปีที่พระเยซูประสูติ","ปีที่สร้างกรุงโรม","ปีที่ค้นพบทวีปอเมริกา"]'::jsonb, 1, 'คริสต์ศักราชเริ่มนับปี ค.ศ. 1 จากปีที่พระเยซูคริสต์ประสูติ'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] การเทียบ พ.ศ. และ ค.ศ.', 'medium', 'mcq', 'การแปลง พ.ศ. ให้เป็น ค.ศ. ต้องนำตัวเลขใดมาลบออก?', '["543","621","1181","2324"]'::jsonb, 0, 'พ.ศ. เริ่มก่อน ค.ศ. อยู่ 543 ปี ดังนั้น ค.ศ. = พ.ศ. - 543 (เช่น 2567 - 543 = 2024)'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] ฮิจเราะห์ศักราช (ฮ.ศ.)', 'hard', 'mcq', 'ฮิจเราะห์ศักราช (ฮ.ศ.) เป็นศักราชที่ใช้ในศาสนาใด และเริ่มนับจากเหตุการณ์ใด?', '["ศาสนาพุทธ เริ่มนับวันตรัสรู้","ศาสนาคริสต์ เริ่มนับวันล้างบาป","ศาสนาอิสลาม เริ่มนับจากปีที่ท่านนบีมุฮัมมัดอพยพจากเมืองมักกะฮ์ไปยังเมืองมะดีนะฮ์","ศาสนาพราหมณ์ เริ่มนับวันสร้างโลก"]'::jsonb, 2, 'ฮิจเราะห์ศักราชเริ่มนับเมื่อท่านนบีมุฮัมมัดนำชาวมุสลิมอพยพ (ฮิจเราะห์) จากมักกะฮ์ไปมะดีนะฮ์'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] รัตนโกสินทร์ศก (ร.ศ.)', 'hard', 'mcq', 'รัตนโกสินทร์ศก (ร.ศ.) เริ่มนับ ร.ศ. 1 ตรงกับปีใด?', '["ปีที่สถาปนากรุงสุโขทัย","ปีที่สถาปนากรุงศรีอยุธยา","ปีที่พระบาทสมเด็จพระพุทธยอดฟ้าจุฬาโลกมหาราช (ร.1) สถาปนากรุงรัตนโกสินทร์ (พ.ศ. 2325)","ปีที่เปลี่ยนแปลงการปกครอง พ.ศ. 2475"]'::jsonb, 2, 'ร.ศ. เริ่มนับ ร.ศ. 1 ในปี พ.ศ. 2325 ซึ่งเป็นปีที่สถาปนากรุงเทพฯ เป็นราชธานี'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] ประเภทของหลักฐานทางประวัติศาสตร์: หลักฐานชั้นต้น', 'easy', 'mcq', 'หลักฐานทางประวัติศาสตร์ในข้อใดจัดเป็น "หลักฐานชั้นต้น (ปฐมภูมิ)"?', '["ศิลาจารึกหลักที่ 1 ที่สร้างขึ้นในสมัยสุโขทัย","หนังสือแบบเรียนประวัติศาสตร์ที่เขียนขึ้นเมื่อวาน","ภาพยนตร์ย้อนยุคอิงประวัติศาสตร์","บทความวิเคราะห์ประวัติศาสตร์ในอินเทอร์เน็ต"]'::jsonb, 0, 'หลักฐานชั้นต้นคือหลักฐานที่ถูกบันทึกหรือสร้างขึ้นโดยผู้ที่อยู่ในเหตุการณ์หรือช่วงเวลาที่เกิดเหตุการณ์นั้นจริง'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] หลักฐานชั้นรอง (ทุติยภูมิ)', 'medium', 'mcq', 'ข้อใดจัดเป็น "หลักฐานชั้นรอง"?', '["โครงกระดูกมนุษย์โบราณ","เครื่องปั้นดินเผาบ้านเชียง","หนังสือประวัติศาสตร์สุโขทัยที่นักวิชาการเรียบเรียงขึ้นในปัจจุบัน","กำแพงเมืองโบราณ"]'::jsonb, 2, 'หลักฐานชั้นรองถูกรวบรวมและเรียบเรียงขึ้นภายหลังจากเหตุการณ์นั้นผ่านพ้นไปแล้ว โดยอาศัยข้อมูลจากหลักฐานชั้นต้น'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] หลักฐานที่เป็นลายลักษณ์อักษร', 'easy', 'mcq', 'หลักฐานในข้อใดเป็น "หลักฐานที่เป็นลายลักษณ์อักษร"?', '["จดหมายเหตุวันวลิต","ขวานหินขัด","ลูกปัดแก้วโบราณ","ซากเจดีย์เก่า"]'::jsonb, 0, 'หลักฐานที่เป็นลายลักษณ์อักษรคือหลักฐานที่มีการบันทึกด้วยตัวหนังสือ เช่น ศิลาจารึก พงศาวดาร จดหมายเหตุ ใบลาน'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] หลักฐานที่ไม่เป็นลายลักษณ์อักษร', 'easy', 'mcq', 'ข้อใดเป็นหลักฐานทางประวัติศาสตร์ที่ "ไม่เป็นลายลักษณ์อักษร"?', '["พงศาวดารกรุงศรีอยุธยา","ศิลาจารึกวัดศรีชุม","หม้อดินเผาลายเขียนสีบ้านเชียง","สนธิสัญญาเบาว์ริง"]'::jsonb, 2, 'โบราณวัตถุ โบราณสถาน โครงกระดูก อาวุธ เครื่องประดับ จัดเป็นหลักฐานที่ไม่เป็นลายลักษณ์อักษร'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/2] แหล่งโบราณคดีบ้านเชียง', 'medium', 'mcq', 'แหล่งโบราณคดี "บ้านเชียง" ซึ่งได้รับการขึ้นทะเบียนเป็นมรดกโลกทางวัฒนธรรม ตั้งอยู่ในจังหวัดใด?', '["จังหวัดเชียงใหม่","จังหวัดอุดรธานี","จังหวัดขอนแก่น","จังหวัดนครราชสีมา"]'::jsonb, 1, 'แหล่งโบราณคดีบ้านเชียงตั้งอยู่ที่ อ.หนองหาน จ.อุดรธานี มีชื่อเสียงด้านภาชนะดินเผาลายเขียนสีแดงและเครื่องสำริด'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/2] เอกลักษณ์ของเครื่องปั้นดินเผาบ้านเชียง', 'easy', 'mcq', 'ลักษณะเด่นของภาชนะดินเผาที่พบที่บ้านเชียงยุคปลายคืออะไร?', '["เป็นหม้อเคลือบสีเขียวมรกต","เป็นภาชนะดินเผาลายก้นหอยเขียนด้วยสีแดง","ทำจากทองคำบริสุทธิ์แกะสลัก","มีตัวหนังสือภาษาอังกฤษสลักไว้"]'::jsonb, 1, 'ภาชนะบ้านเชียงยุคปลายมีเอกลักษณ์ที่ลายเขียนสีแดงเป็นลวดลายก้นหอย ลายเส้นโค้งเรขาคณิตสวยงาม'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/2] แหล่งโบราณคดีถ้ำผีแมน', 'hard', 'mcq', 'แหล่งโบราณคดียุคหินเก่าและหินกลาง "ถ้ำผีแมน" พบในจังหวัดใดของประเทศไทย?', '["จังหวัดแม่ฮ่องสอน","จังหวัดกาญจนบุรี","จังหวัดกระบี่","จังหวัดสุราษฎร์ธานี"]'::jsonb, 0, 'ถ้ำผีแมนตั้งอยู่ใน อ.ปางมะผ้า จ.แม่ฮ่องสอน พบหลักฐานโลงไม้รูปเรือและเครื่องมือหินกะเทาะโบราณ'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/2] แหล่งโบราณคดีเมืองอู่ทอง', 'medium', 'mcq', 'เมืองโบราณอู่ทองในจังหวัดสุพรรณบุรี เคยเป็นศูนย์กลางความเจริญของอาณาจักรโบราณใด?', '["อาณาจักรทวารวดี","อาณาจักรล้านนา","อาณาจักรศรีวิชัย","อาณาจักรสุโขทัย"]'::jsonb, 0, 'เมืองโบราณอู่ทองและนครปฐมโบราณเป็นศูนย์กลางวัฒนธรรมทวารวดีที่นับถือพระพุทธศาสนานิกายเถรวาทในลุ่มน้ำเจ้าพระยา'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/2] โบราณวัตถุสัญลักษณ์ธรรมจักรศิลา', 'medium', 'mcq', '"ธรรมจักรศิลาพร้อมกวางหมอบ" เป็นศิลปะโบราณเนื่องในศาสนาพุทธสมัยอาณาจักรใด?', '["ทวารวดี","ศรีวิชัย","อยุธยา","ลพบุรี"]'::jsonb, 0, 'ธรรมจักรศิลาพร้อมกวางหมอบเป็นเอกลักษณ์ของศิลปะทวารวดี แสดงถึงการเผยแผ่พระธรรมจักรในดินแดนไทย'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/2] แหล่งโบราณคดีเมืองโบราณศรีเทพ', 'hard', 'mcq', '"เมืองโบราณศรีเทพ" มรดกโลกทางวัฒนธรรมแห่งใหม่ของไทย ตั้งอยู่ในจังหวัดใด?', '["จังหวัดเพชรบูรณ์","จังหวัดลพบุรี","จังหวัดนครสวรรค์","จังหวัดสระบุรี"]'::jsonb, 0, 'เมืองโบราณศรีเทพตั้งอยู่ใน อ.ศรีเทพ จ.เพชรบูรณ์ ได้รับการขึ้นทะเบียนเป็นมรดกโลกโดยยูเนสโกในปี พ.ศ. 2566'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/2] ภาพเขียนสีก่อนประวัติศาสตร์', 'medium', 'mcq', 'ภาพเขียนสีผาแต้ม ริมแม่น้ำโขง จังหวัดอุบลราชธานี มีลักษณะภาพอย่างไร?', '["ภาพลายไทยกนกเปลว","ภาพคน ช้าง ปลาบึก และลวดลายเรขาคณิตสีแดงทึบ","ภาพตัวอักษรจีนโบราณ","ภาพแผนที่ดาวเทียม"]'::jsonb, 1, 'ผาแต้มมีภาพเขียนสีอายุราว 3,000 ปี แสดงภาพฝ่ามือ ภาพสัตว์ขนาดใหญ่ เช่น ปลาบึก ช้าง และวิถีชีวิตคนโบราณ'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] การตรวจสอบความถูกต้องของหลักฐาน', 'hard', 'mcq', 'ก่อนนำหลักฐานทางประวัติศาสตร์มาสรุปเป็นข้อเท็จจริง ต้องผ่านขั้นตอนใดก่อน?', '["นำไปตั้งแสดงในพิพิธภัณฑ์ทันที","การประเมินความน่าเชื่อถือและการวิพากษ์หลักฐาน","การสวดมนต์ขอขมา","การแจกจ่ายให้คนทั่วไปอ่าน"]'::jsonb, 1, 'ขั้นตอนการประเมินคุณค่าหรือวิพากษ์หลักฐาน (ภายนอกและภายใน) ช่วยตรวจสอบว่าเป็นของจริงหรือไม่และมีความน่าเชื่อถือเพียงใด'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] ศิลาจารึกหลักที่ 1', 'easy', 'mcq', 'ศิลาจารึกหลักที่ 1 (จารึกพ่อขุนรามคำแหง) สลักด้วยตัวอักษรชนิดใด?', '["อักษรขอมโบราณ","อักษรลายสือไทย","อักษรปัลลวะ","อักษรมอญโบราณ"]'::jsonb, 1, 'พ่อขุนรามคำแหงทรงประดิษฐ์อักษรลายสือไทยขึ้นในปี พ.ศ. 1826 และจารึกลงบนแท่งศิลา'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] สถานที่เก็บรักษาหลักฐานทางประวัติศาสตร์', 'easy', 'mcq', 'หน่วยงานใดของทางราชการมีหน้าที่รวบรวม เก็บรักษา และจัดแสดงโบราณวัตถุของชาติ?', '["สำนักหอสมุดแห่งชาติ","พิพิธภัณฑสถานแห่งชาติ กรมศิลปากร","กรมการศาสนา","สำนักงานตำรวจแห่งชาติ"]'::jsonb, 1, 'พิพิธภัณฑสถานแห่งชาติ สังกัดกรมศิลปากร มีหน้าที่อนุรักษ์ จัดแสดง และเผยแพร่ความรู้เกี่ยวกับโบราณวัตถุและศิลปวัตถุ'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] การอนุรักษ์โบราณสถาน', 'easy', 'mcq', 'เมื่อไปทัศนศึกษาโบราณสถาน นักเรียนควรปฏิบัติตนอย่างไร?', '["ขีดเขียนชื่อตนเองไว้บนผนังศิลาแลงเป็นที่ระลึก","ปีนป่ายขึ้นไปบนองค์พระพุทธรูปเพื่อถ่ายรูป","ปฏิบัติตามป้ายเตือน ไม่สัมผัสหรือทำลายโบราณสถาน และช่วยกันรักษาความสะอาด","เก็บก้อนหินโบราณกลับมาเป็นของสะสมที่บ้าน"]'::jsonb, 2, 'การปฏิบัติตามกฎ ไม่ปีนป่าย ไม่ขีดเขียน และไม่นำโบราณวัตถุออกจากพื้นที่ เป็นการช่วยอนุรักษ์มรดกทางวัฒนธรรม'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/1] การสถาปนาอาณาจักรสุโขทัย', 'easy', 'mcq', 'ใครคือปฐมกษัตริย์ (กษัตริย์องค์แรก) ผู้สถาปนาอาณาจักรสุโขทัยและราชวงศ์พระร่วง?', '["พ่อขุนรามคำแหงมหาราช","พ่อขุนศรีอินทราทิตย์ (พ่อขุนบางกลางหาว)","พระมหาธรรมราชาที่ 1 (พญาลิไทย)","สมเด็จพระรามาธิบดีที่ 1"]'::jsonb, 1, 'พ่อขุนบางกลางหาวได้รับสถาปนาเป็น "พ่อขุนศรีอินทราทิตย์" ปฐมกษัตริย์แห่งราชวงศ์พระร่วง อาณาจักรสุโขทัย เมื่อประมาณ พ.ศ. 1792'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/1] พันธมิตรผู้ร่วมกอบกู้อิสรภาพสุโขทัย', 'medium', 'mcq', 'พ่อขุนศรีอินทราทิตย์ได้ร่วมมือกับผู้นำเมืองราดท่านใดในการขับไล่ขอมสบาดโขลญลำพงออกจากสุโขทัย?', '["พ่อขุนผาเมือง","พ่อขุนรามคำแหง","พญางำเมือง","พญามังราย"]'::jsonb, 0, 'พ่อขุนบางกลางหาว (เจ้าเมืองบางยาง) ร่วมมือกับพ่อขุนผาเมือง (เจ้าเมืองราด) รวบรวมกำลังขับไล่ขอมจนสำเร็จ'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/1] สาเหตุการเลือกตั้งเมืองสุโขทัยเป็นราชธานี', 'medium', 'mcq', 'ชัยภูมิของกรุงสุโขทัยมีความเหมาะสมในการตั้งราชธานีอย่างไร?', '["มีทางออกสู่ทะเลลึกโดยตรง","ตั้งอยู่บริเวณที่ราบเชิงเขา มีแม่น้ำยมและลำน้ำสาขาไหลผ่าน ดินอุดมสมบูรณ์ และมีแนวเทือกเขาช่วยป้องกันลมมรสุม","เป็นเกาะกลางแม่น้ำขนาดใหญ่","อยู่บนยอดเขาสูงชันข้าศึกเข้าไม่ถึง"]'::jsonb, 1, 'สุโขทัยตั้งอยู่ริมแม่น้ำยม มีทรัพยากรธรรมชาติอุดมสมบูรณ์ เหมาะแก่การเกษตรและการคมนาคมทางบกและทางน้ำ'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] รูปแบบการปกครองสมัยสุโขทัยตอนต้น', 'easy', 'mcq', 'การปกครองของสุโขทัยในยุคเริ่มต้นมีลักษณะความสัมพันธ์ระหว่างกษัตริย์กับราษฎรแบบใด?', '["ระบอบสมบูรณาญาสิทธิราชย์แบบเทวราชา","การปกครองแบบพ่อปกครองลูก (ปิตุราชา)","การปกครองแบบประชาธิปไตย","การปกครองแบบขุนนาง"]'::jsonb, 1, 'สุโขทัยตอนต้นปกครองแบบ "พ่อปกครองลูก" กษัตริย์ใช้คำนำหน้าว่า "พ่อขุน" ดูแลราษฎรอย่างใกล้ชิดเสมือนคนในครอบครัว'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] การรับเรื่องร้องทุกข์ของพ่อขุนรามคำแหง', 'easy', 'mcq', 'ในสมัยพ่อขุนรามคำแหงมหาราช ราษฎรที่มีเรื่องเดือดร้อนใจสามารถร้องทุกข์ต่อพระองค์ได้อย่างไร?', '["ส่งจดหมายอิเล็กทรอนิกส์","ไปสั่นกระดิ่งที่แขวนไว้ที่ประตูเมือง","เขียนป้ายประท้วงหน้าพระราชวัง","ต้องจ่ายเงินว่าจ้างขุนนางให้ไปกราบทูล"]'::jsonb, 1, 'พระองค์โปรดให้แขวนกระดิ่งไว้ที่ซุ้มประตูเมือง เมื่อราษฎรเดือดร้อนก็มาสั่นกระดิ่ง พระองค์จะเสด็จมาชำระความด้วยพระองค์เอง'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] การปกครองสมัยสุโขทัยตอนปลาย: ธรรมราชา', 'hard', 'mcq', 'ในสมัยพระมหาธรรมราชาที่ 1 (พญาลิไทย) รูปแบบการปกครองเปลี่ยนมาใช้หลักธรรมใดเป็นแนวทาง?', '["ทศพิธราชธรรม (การปกครองแบบธรรมราชา)","กฎหมายโรมัน","หลักนิติธรรมสากล","หลักอำนาจเด็ดขาด"]'::jsonb, 0, 'พระมหาธรรมราชาที่ 1 ทรงนำหลักธรรมทางพุทธศาสนา เช่น ทศพิธราชธรรม มาใช้ในการปกครองบ้านเมือง เรียกว่า "ธรรมราชา"'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] เศรษฐกิจสุโขทัย: เสรีภาพทางการค้า', 'easy', 'mcq', 'ข้อความในศิลาจารึก "ใครจักใคร่ค้าช้างค้า ใครจักใคร่ค้าม้าค้า..." แสดงถึงลักษณะทางเศรษฐกิจด้านใดของสุโขทัย?', '["การผูกขาดการค้าโดยกษัตริย์","การค้าขายแบบเสรี โดยไม่มีการเก็บภาษีจังกอบ (ภาษีผ่านด่าน)","การห้ามประชาชนเลี้ยงสัตว์","การค้าขายเฉพาะกับชาวต่างชาติ"]'::jsonb, 1, 'แสดงถึงนโยบายการค้าแบบเสรี รัฐไม่เก็บภาษีผ่านด่าน (จังกอบ) ทำให้พ่อค้าเดินทางมาค้าขายอย่างคึกคัก'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] ตลาดในสมัยสุโขทัย', 'medium', 'mcq', 'ตลาดค้าขายสินค้าในสมัยกรุงสุโขทัยมีชื่อเรียกว่าอะไร?', '["ตลาดปสาน","ตลาดน้ำ","ตลาดนัดคลองถม","ตลาดวโรรส"]'::jsonb, 0, 'ตลาดในสมัยสุโขทัยเรียกว่า "ตลาดปสาน" ซึ่งได้รับอิทธิพลมาจากคำว่า บาซาร์ (Bazaar) ในภาษาเปอร์เซีย'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] สินค้าส่งออกสำคัญของสุโขทัย', 'easy', 'mcq', 'สินค้าหัตถกรรมเครื่องปั้นดินเผาเคลือบที่ขึ้นชื่อที่สุดของสุโขทัย ซึ่งส่งออกไปขายต่างประเทศคือข้อใด?', '["เครื่องเบญจรงค์","เครื่องสังคโลก","เครื่องลายคราม","เครื่องแก้วเจียระไน"]'::jsonb, 1, 'เครื่องสังคโลกผลิตจากเตาทุเรียงในเมืองสุโขทัยและศรีสัชนาลัย เป็นสินค้าส่งออกสำคัญไปยังดินแดนเอเชียตะวันออกเฉียงใต้และญี่ปุ่น'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] การจัดการน้ำในสุโขทัย: สรีดภงส์', 'medium', 'mcq', 'ภูมิปัญญาการชลประทานสร้างเขื่อนหรือทำนบดินกักเก็บน้ำของชาวสุโขทัย เรียกว่าอะไร?', '["สรีดภงส์","บาราย","ฝายแม้ว","คลองชลประทาน"]'::jsonb, 0, 'สรีดภงส์ หรือทำนบพระร่วง เป็นทำนบดินกั้นน้ำระหว่างหุบเขา เพื่อกักเก็บน้ำไว้ใช้และระบายเข้าสู่คูเมืองและตระพังในฤดูแล้ง'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] สระน้ำหรืออ่างเก็บน้ำในเมืองสุโขทัย', 'medium', 'mcq', 'สระน้ำขนาดใหญ่ที่ขุดขึ้นภายในและรอบตัวเมืองสุโขทัยเพื่อกักเก็บน้ำสะอาดไว้ใช้ เรียกว่าอะไร?', '["หนองน้ำ","ตระพัง","บึง","แอ่ง"]'::jsonb, 1, 'ตระพัง (เช่น ตระพังเงิน ตระพังทอง ตระพังตระกวน) คือสระน้ำที่ขุดขึ้นเพื่อกักเก็บน้ำใช้อุปโภคบริโภคและใช้ในพิธีกรรมทางศาสนา'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] ศาสนาในสมัยสุโขทัย', 'medium', 'mcq', 'พ่อขุนรามคำแหงมหาราชทรงอาราธนาพระสงฆ์จากเมืองใดมาเผยแผ่พระพุทธศาสนานิกายเถรวาท ลัทธิลังกาวงศ์ ที่สุโขทัย?', '["เมืองนครศรีธรรมราช","เมืองเชียงใหม่","เมืองละโว้ (ลพบุรี)","เมืองพุกาม"]'::jsonb, 0, 'ทรงอาราธนาพระมหาเถรสังฆราชจากเมืองนครศรีธรรมราช ผู้มีความเชี่ยวชาญพระไตรปิฎก มาจำพรรษาที่วัดอรัญญิก กรุงสุโขทัย'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] การประดิษฐ์อักษรไทย', 'easy', 'mcq', 'พ่อขุนรามคำแหงมหาราชทรงประดิษฐ์ "ลายสือไทย" ขึ้นในปี พ.ศ. ใด?', '["พ.ศ. 1792","พ.ศ. 1826","พ.ศ. 1900","พ.ศ. 2000"]'::jsonb, 1, 'ทรงดัดแปลงอักษรขอมและอักษรมอญโบราณมาประดิษฐ์เป็นลายสือไทยขึ้นเมื่อ พ.ศ. 1826 อันเป็นต้นกำเนิดอักษรไทยในปัจจุบัน'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] วรรณกรรมชิ้นเอกสมัยสุโขทัย: ไตรภูมิพระร่วง', 'medium', 'mcq', 'วรรณกรรมเรื่อง "ไตรภูมิพระร่วง" พระราชนิพนธ์โดยกษัตริย์พระองค์ใด และมีเนื้อหาเกี่ยวกับเรื่องใด?', '["พ่อขุนรามคำแหงมหาราช เรื่องการรบ","พระมหาธรรมราชาที่ 1 (พญาลิไทย) เรื่องนรก สวรรค์ กฎแห่งกรรม และการทำความดี","พ่อขุนศรีอินทราทิตย์ เรื่องการค้าขาย","สมเด็จพระนเรศวรมหาราช เรื่องยุทธหัตถี"]'::jsonb, 1, 'พญาลิไทยทรงพระราชนิพนธ์เพื่อสอนศีลธรรม ให้ประชาชนเกรงกลัวต่อบาปและมุ่งทำความดีตามหลักไตรภูมิ (กามภูมิ รูปภูมิ อรูปภูมิ)'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] ศิลปะสถาปัตยกรรมสุโขทัย: เจดีย์ทรงพุ่มข้าวบิณฑ์', 'medium', 'mcq', 'เจดีย์ทรง "พุ่มข้าวบิณฑ์" (หรือทรงยอดดอกบัวตูม) เป็นเอกลักษณ์เฉพาะของศิลปกรรมในยุคใด?', '["สุโขทัย","อยุธยา","ธนบุรี","รัตนโกสินทร์"]'::jsonb, 0, 'เจดีย์ทรงพุ่มข้าวบิณฑ์หรือดอกบัวตูม (เช่น ที่วัดมหาธาตุ สุโขทัย) เป็นเจดีย์ศิลปะสุโขทัยแท้บริสุทธิ์'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] พระพุทธรูปศิลปะสุโขทัย', 'easy', 'mcq', 'พระพุทธรูปปางใดที่ถือว่างดงามอ่อนช้อยและโดดเด่นที่สุดในศิลปะสุโขทัย?', '["พระพุทธรูปปางลีลา","พระพุทธรูปปางป่าเลไลยก์","พระพุทธรูปปางนาคปรก","พระพุทธรูปปางไสยาสน์"]'::jsonb, 0, 'พระพุทธรูปปางลีลาสมัยสุโขทัยได้รับการยกย่องว่ามีความงดงาม อ่อนช้อย พริ้วไหวดั่งมีชีวิตมากที่สุดในประวัติศาสตร์ศิลป์ไทย'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] พระพุทธชินราช', 'easy', 'mcq', 'พระพุทธรูปศักดิ์สิทธิ์คู่บ้านคู่เมืองที่มีพุทธลักษณะงดงามที่สุดในประเทศไทย สร้างขึ้นในสมัยสุโขทัย ประดิษฐาน ณ วัดพระศรีรัตนมหาธาตุ จังหวัดพิษณุโลก คือพระพุทธรูปองค์ใด?', '["พระแก้วมรกต","พระพุทธชินราช","พระพุทธโสธร","หลวงพ่อโต"]'::jsonb, 1, 'พระพุทธชินราชสร้างขึ้นในรัชสมัยพระมหาธรรมราชาที่ 1 (พญาลิไทย) มีพุทธลักษณะงดงามสมบูรณ์แบบที่สุด'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] วีรกรรมของพ่อขุนรามคำแหงในวัยเยาว์', 'medium', 'mcq', 'พระนาม "รามคำแหง" ได้รับพระราชทานจากพระราชบิดาหลังทรงกระทำวีรกรรมใดเมื่อพระชนมายุ 19 พรรษา?', '["ทรงแต่งบทกลอนชนะเลิศ","ทรงชนช้างชนะขุนสามชน เจ้าเมืองฉอด ที่ยกทัพมาตีเมืองตาก","ทรงเดินทางไปค้าขายถึงประเทศจีน","ทรงสร้างเขื่อนสรีดภงส์สำเร็จ"]'::jsonb, 1, 'เมื่อพระชนมายุ 19 พรรษา ทรงไสช้างเข้าช่วยพระราชบิดาและชนช้างชนะขุนสามชนเจ้าเมืองฉอด พระราชบิดาจึงพระราชทานนามว่า "รามคำแหง" (รามผู้กล้าหาญ)'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] ความสัมพันธ์ระหว่างแว่นแคว้น: สหายสามกษัตริย์', 'hard', 'mcq', '"สามกษัตริย์" ที่ทรงเป็นพระสหายร่วมสาบานและร่วมกันวางผังสร้างเมืองนพบุรีศรีนครพิงค์เชียงใหม่ ประกอบด้วยพระมหากษัตริย์พระองค์ใดบ้าง?', '["พ่อขุนรามคำแหง, พญามังราย, พญางำเมือง","พ่อขุนศรีอินทราทิตย์, พ่อขุนผาเมือง, พระยาลิไทย","สมเด็จพระนเรศวร, สมเด็จพระเอกาทศรถ, พระสุพรรณกัลยา","พ่อขุนรามคำแหง, พระมหาธรรมราชา, ขุนสามชน"]'::jsonb, 0, 'พญามังราย (ล้านนา), พ่อขุนรามคำแหง (สุโขทัย), และพญางำเมือง (พะเยา) ทรงเป็นพระสหายสนิทร่วมกันสร้างเมืองเชียงใหม่'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] พระมารดาของพ่อขุนรามคำแหง', 'medium', 'mcq', 'พระมเหสีของพ่อขุนศรีอินทราทิตย์ พระมารดาของพ่อขุนรามคำแหงมหาราช มีพระนามว่าอย่างไร?', '["นางเสือง","พระนางจามเทวี","ท้าวสุรนารี","นางนพมาศ"]'::jsonb, 0, 'ในศิลาจารึกระบุว่า "พ่อกูชื่อศรีอินทราทิตย์ แม่กูชื่อนางเสือง พี่กูชื่อบานเมือง..."'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] ประเพณีเผาเทียนเล่นไฟ', 'easy', 'mcq', 'ข้อความในศิลาจารึกกล่าวถึงประเพณีลอยกระทงและจุดประทีปโคมไฟในกรุงสุโขทัยว่าอย่างไร?', '["ประเพณีแห่เทียนพรรษา","ประเพณีเผาเทียนเล่นไฟ","ประเพณีสงกรานต์","ประเพณีตักบาตรเทโว"]'::jsonb, 1, 'ในศิลาจารึกระบุว่าชาวสุโขทัยมักร่วมใจกันทำบุญและ "เผาเทียนเล่นไฟ" ในเทศกาลเดือนสิบสอง'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] การสิ้นสุดความเป็นราชธานีของสุโขทัย', 'hard', 'mcq', 'ในเวลาต่อมา อาณาจักรสุโขทัยได้ถูกรวมเข้าเป็นส่วนหนึ่งของอาณาจักรไทยใด?', '["อาณาจักรล้านนา","อาณาจักรอยุธยา","อาณาจักรธนบุรี","อาณาจักรขอม"]'::jsonb, 1, 'สุโขทัยค่อยๆ อ่อนแอลงและในที่สุดถูกผนวกรวมเข้าเป็นมณฑลราชธานีฝ่ายเหนือของอาณาจักรอยุธยาในสมัยสมเด็จพระบรมไตรโลกนาถ'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] การแสดงความกตัญญูกตเวทีของพ่อขุนรามคำแหง', 'easy', 'mcq', 'จากข้อความในจารึก "เมื่อกูขึ้นใหญ่ได้สิบเก้าเข้า... กูไปทวยพ่อกู กูบำเรอแก่พ่อกู กูบำเรอแก่แม่กู..." แสดงถึงคุณธรรมข้อใดของพ่อขุนรามคำแหง?', '["ความกตัญญูกตเวทีต่อบิดามารดา","ความร่ำรวยมั่งคั่ง","ความดุร้ายน่าเกรงขาม","ความสามารถด้านการค้า"]'::jsonb, 0, 'แสดงถึงความกตัญญูและการปรนนิบัติดูแลบิดามารดาด้วยความรักและความเคารพ'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] การติดต่อทางการทูตกับต่างประเทศ', 'medium', 'mcq', 'ในสมัยสุโขทัยมีการส่งคณะราชทูตและสำเภาไปเจริญสัมพันธไมตรีและการค้ากับประเทศมหาอำนาจใด?', '["ประเทศอังกฤษ","ประเทศจีน (ราชวงศ์หยวน)","ประเทศโปรตุเกส","ประเทศญี่ปุ่น"]'::jsonb, 1, 'สุโขทัยส่งเครื่องราชบรรณาการไปเจริญสัมพันธไมตรีกับจักรพรรดิจีนราชวงศ์หยวน และนำช่างจีนมาช่วยพัฒนาการทำเครื่องเคลือบสังคโลก'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] อุทยานประวัติศาสตร์สุโขทัย มรดกโลก', 'easy', 'mcq', 'เมืองประวัติศาสตร์สุโขทัยและเมืองบริวาร (ศรีสัชนาลัย และกำแพงเพชร) ได้รับการยกย่องจากยูเนสโกให้เป็นสิ่งใด?', '["มรดกโลกทางวัฒนธรรม","มรดกโลกทางธรรมชาติ","เมืองหลวงสำรอง","เขตเศรษฐกิจพิเศษ"]'::jsonb, 0, 'ยูเนสโกประกาศให้อุทยานประวัติศาสตร์สุโขทัย ศรีสัชนาลัย และกำแพงเพชร เป็นแหล่งมรดกโลกทางวัฒนธรรมร่วมกันในปี พ.ศ. 2534'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] วัดมหาธาตุ สุโขทัย', 'medium', 'mcq', 'วัดสำคัญที่เป็นศูนย์กลางทางศาสนาและการปกครอง ตั้งอยู่กึ่งกลางเมืองสุโขทัยคือวัดใด?', '["วัดพระศรีสรรเพชญ์","วัดมหาธาตุ","วัดพระแก้ว","วัดชนะสงคราม"]'::jsonb, 1, 'วัดมหาธาตุ สุโขทัย เป็นวัดหลวงกลางเมือง มีเจดีย์ประธานทรงพุ่มข้าวบิณฑ์บรรจุพระบรมสารีริกธาตุ'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] วัดศรีชุมและอุโมงค์ภาพชาดก', 'hard', 'mcq', 'มณฑปวัดศรีชุม สุโขทัย มีชื่อเสียงโดดเด่นจากสิ่งใด?', '["พระอจนะ (พระพุทธรูปปูนปั้นปางมารวิชัยขนาดใหญ่) และภาพสลักหินชนวนเรื่องชาดกในช่องบันไดเพดาน","พระแก้วมรกตจำลอง","หอระฆังทองคำแท้","เสาหินอโศก"]'::jsonb, 0, 'วัดศรีชุมมี "พระพุทธรูปพูดได้" (พระอจนะ) และช่องทางเดินแคบๆ ในผนังที่มีภาพลายเส้นหินชนวนเล่าเรื่องชาดก 550 ชาติ'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] ภูมิปัญญาการทำเครื่องปั้นดินเผา: เตาเผาสุโขทัย', 'medium', 'mcq', 'เตาเผาโบราณที่ใช้เผาเครื่องสังคโลกในสมัยสุโขทัย มีชื่อเรียกว่าอะไร?', '["เตาทุเรียง","เตาหลอมเหล็ก","เตาอบรมยา","เตาถ่านหิน"]'::jsonb, 0, 'เตาทุเรียง (หรือเตาประทุน) เป็นเตาเผาดินเผาโบราณทรงรีคล้ายประทุนเรือ ใช้เผาเครื่องสังคโลกอุณหภูมิสูง'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] คุณค่าของการศึกษาประวัติศาสตร์สุโขทัย', 'easy', 'mcq', 'การศึกษาประวัติศาสตร์สมัยสุโขทัยมีประโยชน์ต่อนักเรียนในปัจจุบันอย่างไร?', '["ทำให้ทราบรากเหง้า ตัวอักษรไทย วัฒนธรรม และเกิดความภาคภูมิใจในความเป็นชาติไทย","ทำให้สามารถสร้างเครื่องสังคโลกขายได้รวย","เพื่อให้ท่องจำชื่อพระมหากษัตริย์ไปสอบเท่านั้น","ทำให้เดินทางไปท่องเที่ยวได้โดยไม่ต้องซื้อตั๋ว"]'::jsonb, 0, 'ช่วยให้เข้าใจความเป็นมาของชาติ ภาษา ตัวอักษรไทย ศิลปวัฒนธรรม และเกิดความหวงแหนภูมิปัญญาบรรพบุรุษ'),
('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] การสืบทอดมรดกทางวัฒนธรรม', 'easy', 'mcq', 'หน้าที่สำคัญที่สุดของเยาวชนไทยต่อประวัติศาสตร์และโบราณสถานของชาติคือข้อใด?', '["ช่วยกันอนุรักษ์ ดูแลรักษา ไม่ทำลาย และเผยแพร่ความรู้แก่ผู้อื่นอย่างถูกต้อง","ปล่อยให้เจ้าหน้าที่รัฐดูแลเพียงฝ่ายเดียว","นำสีสเปรย์ไปพ่นตกแต่งโบราณสถานให้ทันสมัย","ย้ายโบราณสถานมาไว้ที่โรงเรียน"]'::jsonb, 0, 'เยาวชนมีหน้าที่ศึกษาให้เข้าใจ ช่วยดูแลรักษา และไม่ทำลายโบราณสถานเพื่อให้คงอยู่สืบไปสู่อนุชนรุ่นหลัง');
